"""Pure process metrics instrumentation for deep research operation traces.

Node transitions are the sole input. Tracker state never reads wall-clock time
for ``ProcessMetrics``: duration is derived from transition timestamps, so an
identical transition sequence always yields identical metrics.

State conventions consumed from ``NodeTransition.output_state``:

* ``retrieved_document_ids``: sequence of document identifiers retrieved by the
  node, used for per-iteration breadth and total retrieved documents
* ``follow_up_queries``: sequence of follow-up query strings generated by the
  node
* ``primary_query_count``: optional integer count of primary queries
* ``report_word_count``: optional integer final report word count
"""

from __future__ import annotations

from datetime import UTC, datetime
from math import isfinite
from typing import NamedTuple

from pydantic import BaseModel, ConfigDict, Field, field_validator

_RATIO_FIELDS = (
    "brief_to_report_coverage_ratio",
    "follow_up_depth",
    "breadth_vs_depth_ratio",
)


class ProcessMetricsError(Exception):
    """Raised when process metric tracking is used outside its contract."""


class NodeTransition(NamedTuple):
    """A single supervisor-researcher node transition."""

    node_name: str
    timestamp: datetime
    input_state: dict[str, object]
    output_state: dict[str, object]
    tool_calls: list[str]


def _checked_ratio(value: float) -> float:
    if not isfinite(value) or value < 0:
        message = "ratio metrics must be finite and non-negative"
        raise ValueError(message)
    return value


class ProcessMetrics(BaseModel):
    """Metrics computed from deep research operation traces."""

    model_config = ConfigDict(extra="forbid", frozen=True)

    brief_to_report_coverage_ratio: float
    follow_up_depth: float
    breadth_vs_depth_ratio: float
    total_node_transitions: int = Field(ge=0)
    total_tool_calls: int = Field(ge=0)
    total_duration_seconds: float = Field(ge=0)

    @field_validator(*_RATIO_FIELDS)
    @classmethod
    def _validate_ratio(cls, value: float) -> float:
        return _checked_ratio(value)

    @field_validator("total_duration_seconds")
    @classmethod
    def _validate_duration(cls, value: float) -> float:
        return _checked_ratio(value)


class ProcessMetricSnapshot(BaseModel):
    """Point-in-time process metrics record for one deep research operation."""

    model_config = ConfigDict(extra="forbid", frozen=True)

    operation_id: str
    start_time: datetime
    end_time: datetime
    initial_query: str
    final_report_word_count: int = Field(ge=0)
    total_retrieved_documents: int = Field(ge=0)
    unique_follow_up_queries: int = Field(ge=0)
    primary_query_count: int = Field(ge=0)
    total_iterations: int = Field(ge=0)
    unique_documents_per_iteration: list[int]
    brief_to_report_coverage_ratio: float
    follow_up_depth: float
    breadth_vs_depth_ratio: float

    @field_validator(*_RATIO_FIELDS)
    @classmethod
    def _validate_ratio(cls, value: float) -> float:
        return _checked_ratio(value)


class ProcessMetricsReport(BaseModel):
    """Aggregate process metrics across multiple operations."""

    model_config = ConfigDict(extra="forbid", frozen=True)

    average_brief_to_report_coverage_ratio: float
    average_follow_up_depth: float
    average_breadth_vs_depth_ratio: float
    total_operations_analyzed: int = Field(ge=0)

    @field_validator(
        "average_brief_to_report_coverage_ratio",
        "average_follow_up_depth",
        "average_breadth_vs_depth_ratio",
    )
    @classmethod
    def _validate_ratio(cls, value: float) -> float:
        return _checked_ratio(value)


def _string_list(value: object) -> list[str]:
    if not isinstance(value, (list, tuple, set, frozenset)):
        return []
    return [item for item in value if isinstance(item, str)]


def _unique_strings(transitions: list[NodeTransition], key: str) -> set[str]:
    return {
        item
        for transition in transitions
        for item in _string_list(transition.output_state.get(key))
    }


def _final_non_negative_int(transitions: list[NodeTransition], key: str) -> int | None:
    for transition in reversed(transitions):
        value = transition.output_state.get(key)
        if isinstance(value, int) and not isinstance(value, bool) and value >= 0:
            return value
    return None


def _safe_ratio(numerator: float, denominator: float) -> float:
    if denominator <= 0:
        return 0.0
    value = numerator / denominator
    if not isfinite(value) or value < 0:
        return 0.0
    return value


def _duration_seconds(transitions: list[NodeTransition]) -> float:
    if len(transitions) < 2:
        return 0.0
    timestamps = [transition.timestamp for transition in transitions]
    try:
        return max((max(timestamps) - min(timestamps)).total_seconds(), 0.0)
    except TypeError:
        return 0.0


def _documents_per_iteration(transitions: list[NodeTransition]) -> list[int]:
    return [
        len(set(_string_list(transition.output_state.get("retrieved_document_ids"))))
        for transition in transitions
    ]


def _compute_metrics(transitions: list[NodeTransition], primary_query_count: int) -> ProcessMetrics:
    report_word_count = _final_non_negative_int(transitions, "report_word_count") or 0
    total_retrieved_documents = len(_unique_strings(transitions, "retrieved_document_ids"))
    unique_follow_up_queries = len(_unique_strings(transitions, "follow_up_queries"))
    documents_per_iteration = _documents_per_iteration(transitions)
    breadth = (
        sum(documents_per_iteration) / len(documents_per_iteration)
        if documents_per_iteration
        else 0.0
    )
    return ProcessMetrics(
        brief_to_report_coverage_ratio=_safe_ratio(
            float(total_retrieved_documents), float(report_word_count)
        ),
        follow_up_depth=_safe_ratio(float(unique_follow_up_queries), float(primary_query_count)),
        breadth_vs_depth_ratio=_safe_ratio(breadth, 1.0),
        total_node_transitions=len(transitions),
        total_tool_calls=sum(len(transition.tool_calls) for transition in transitions),
        total_duration_seconds=_duration_seconds(transitions),
    )


class ProcessMetricsTracker:
    """Instrument a supervisor-researcher loop for process metrics."""

    def __init__(self) -> None:
        self._initial_query: str | None = None
        self._node_limit = 0
        self._start_time: datetime | None = None
        self._transitions: list[NodeTransition] = []

    @property
    def node_count(self) -> int:
        return len(self._transitions)

    @property
    def transitions(self) -> tuple[NodeTransition, ...]:
        return tuple(self._transitions)

    def start_tracking(self, initial_query: str, node_limit: int) -> None:
        """Begin tracking a deep research operation, resetting prior state."""
        if node_limit < 0:
            message = "node_limit must be non-negative"
            raise ProcessMetricsError(message)
        self._initial_query = initial_query
        self._node_limit = node_limit
        self._start_time = datetime.now(UTC)
        self._transitions = []

    def record_node_transition(self, transition: NodeTransition) -> None:
        """Append one transition in arrival order, enforcing the node limit."""
        self._require_started("record_node_transition")
        if len(self._transitions) >= self._node_limit:
            message = (
                f"node_limit exceeded: attempted transition {len(self._transitions) + 1} "
                f"of {self._node_limit}"
            )
            raise ProcessMetricsError(message)
        self._transitions.append(transition)

    def compute_metrics(self) -> ProcessMetrics:
        """Compute deterministic metrics from the recorded transitions."""
        self._require_started("compute_metrics")
        primary_query_count = self._primary_query_count()
        return _compute_metrics(self._transitions, primary_query_count)

    def build_snapshot(self, *, operation_id: str) -> ProcessMetricSnapshot:
        """Build a snapshot including the recorded start/end times."""
        self._require_started("build_snapshot")
        start_time = self._start_time
        if start_time is None:
            message = "build_snapshot called before start_tracking"
            raise ProcessMetricsError(message)
        metrics = self.compute_metrics()
        return ProcessMetricSnapshot(
            operation_id=operation_id,
            start_time=start_time,
            end_time=self._transitions[-1].timestamp if self._transitions else start_time,
            initial_query=self._initial_query or "",
            final_report_word_count=(
                _final_non_negative_int(self._transitions, "report_word_count") or 0
            ),
            total_retrieved_documents=len(
                _unique_strings(self._transitions, "retrieved_document_ids")
            ),
            unique_follow_up_queries=len(_unique_strings(self._transitions, "follow_up_queries")),
            primary_query_count=self._primary_query_count(),
            total_iterations=len(self._transitions),
            unique_documents_per_iteration=_documents_per_iteration(self._transitions),
            brief_to_report_coverage_ratio=metrics.brief_to_report_coverage_ratio,
            follow_up_depth=metrics.follow_up_depth,
            breadth_vs_depth_ratio=metrics.breadth_vs_depth_ratio,
        )

    def _require_started(self, operation: str) -> None:
        if self._initial_query is None or self._start_time is None:
            message = f"{operation} called before start_tracking"
            raise ProcessMetricsError(message)

    def _primary_query_count(self) -> int:
        declared = _final_non_negative_int(self._transitions, "primary_query_count")
        if declared is not None:
            return declared
        primary_queries = _unique_strings(self._transitions, "primary_queries")
        if primary_queries:
            return len(primary_queries)
        return 1
